package com.aadil.ecommerce.repositories;import com.aadil.ecommerce.entities.UserEntity;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Repository;import java.util.List;import java.util.Optional;@Repositorypublic interface UserRepository extends JpaRepository<UserEntity,Long> {    Optional<UserEntity> findByEmail (String email);    Page<UserEntity> findByEmailContainingIgnoreCaseOrNameContainingIgnoreCase (String email, String name, Pageable pageable);}